// Region controls share the ordinary object inspector and local placement.
export function installAnomalyControls({container,renderer,changed}){
 const panel=document.createElement('section');panel.className='intrinsic-properties';panel.hidden=true;panel.setAttribute('aria-label','Gravity anomaly properties');
 panel.innerHTML='<h4>GRAVITY ANOMALY</h4><label class="field-label" for="anomalyRadius">REGION RADIUS · LOGARITHMIC</label><input id="anomalyRadius" type="range" min="0" max="15" step=".01"><label class="field-label" for="anomalyRadiusMeters">RADIUS · METERS</label><input id="anomalyRadiusMeters" type="number" min="1" max="1e15" step="any">'+[['anomalyStrength','Distortion',0,3,.05],['anomalyScale','Structure scale',.3,3,.05],['anomalyMotion','Turbulence speed',0,2,.05]].map(([id,label,min,max,step])=>`<div class="range-header"><label for="${id}">${label}</label><output id="${id}Value"></output></div><input id="${id}" type="range" min="${min}" max="${max}" step="${step}">`).join('')+'<p class="control-note">A smooth, body-free lensing region. This illustrative field has no singularity or orbiting children. Use the grid to reveal its structure.</p>';
 container.prepend(panel);let selected=null;const $=id=>panel.querySelector('#'+id);
 const patch=value=>{if(!selected)return;renderer()?.updateObject(selected,value);changed();};
 $('anomalyRadius').addEventListener('input',()=>patch({radiusMeters:10**Number($('anomalyRadius').value),scale:1}));
 $('anomalyRadiusMeters').addEventListener('change',()=>{const radius=Number($('anomalyRadiusMeters').value);if(Number.isFinite(radius)&&radius>=1)patch({radiusMeters:Math.min(1e15,radius),scale:1});});
 for(const key of ['anomalyStrength','anomalyScale','anomalyMotion'])$(key).addEventListener('input',()=>patch({[key]:Number($(key).value)}));
 return {update(object){selected=object?.type==='anomaly'?object.id:null;panel.hidden=!selected;if(!selected)return;const radius=(object.radiusMeters||1)*(object.scale||1),values={anomalyRadius:Math.log10(radius),anomalyRadiusMeters:radius,anomalyStrength:object.anomalyStrength??1.8,anomalyScale:object.anomalyScale??1,anomalyMotion:object.anomalyMotion??1};for(const [key,value]of Object.entries(values)){if(document.activeElement!==$(key))$(key).value=value;const output=$(key+'Value');if(output)output.textContent=Number(value).toFixed(2)+'×';}}};
}
